package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class ConditionalClocksBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  try(var db=h.store.open()){db.update("UPDATE os_clock_policy SET active=0");db.connection.commit();}String calendar="PolicyBrowser"+id();BusinessDeadlineAcceptance.seed(h.store,calendar,PlatformFoundationTest.calendar());
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Clock policies").setExact(true)).press("Enter");page.getByLabel("Record type",new Page.GetByLabelOptions().setExact(true)).selectOption("incident");ServiceOutagesBrowserAcceptance.click(page,"Choose record type");page.getByLabel("Policy name").fill("Priority incident commitment <script>");page.getByLabel("Business calendar",new Page.GetByLabelOptions().setExact(true)).selectOption(calendar);page.getByLabel("Business-minute budget").fill("120");page.getByLabel("Clock purpose").selectOption("resolution");page.getByLabel("Maximum start priority").selectOption("2");page.locator("select[name=state_1]").selectOption("start");page.locator("select[name=state_3]").selectOption("pause");page.locator("select[name=state_6]").selectOption("complete");page.locator("select[name=state_7]").selectOption("cancel");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/clock-policy-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Save clock policy");assertThat(page.locator("main")).containsText("Priority incident commitment <script>");
   try(var db=h.store.open()){db.update("DELETE FROM os_calendar WHERE calendar_id=?",calendar);db.connection.commit();}page.reload();page.getByLabel("Policy availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save clock policy");assertThat(page.locator("main")).containsText("Disabled");try(var db=h.store.open()){assertEquals(0,db.count("SELECT active FROM os_clock_policy WHERE name=?","Priority incident commitment <script>"));}BusinessDeadlineAcceptance.seed(h.store,calendar,PlatformFoundationTest.calendar());page.getByLabel("Policy availability").selectOption("true");ServiceOutagesBrowserAcceptance.click(page,"Save clock policy");
   page.navigate(h.base()+"/record/incident/new");page.locator("input[name=short_description]").fill("Time this priority incident");page.locator("select[name=priority]").selectOption("1");ServiceOutagesBrowserAcceptance.click(page,"Create record →");String record=page.url().substring(page.url().lastIndexOf('/')+1);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View service clocks")).press("Enter");assertThat(page.locator("tbody")).containsText("running");assertThat(page.locator("main")).containsText("Latest outcome: attached");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to record")).press("Enter");RiskAssessmentsBrowserAcceptance.change(page,"2");RiskAssessmentsBrowserAcceptance.change(page,"3");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View service clocks")).press("Enter");assertThat(page.locator("tbody")).containsText("paused");var evidence=page.locator("article").filter(new Locator.FilterOptions().setHasText("Priority incident commitment <script>"));evidence.locator("summary").press("Enter");assertThat(evidence.locator("details")).containsText("paused");ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/clock-policy-history-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to record")).press("Enter");RiskAssessmentsBrowserAcceptance.change(page,"2");RiskAssessmentsBrowserAcceptance.change(page,"6");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View service clocks")).press("Enter");assertThat(page.locator("tbody")).containsText("completed");assertThat(page.locator("main")).containsText("Latest outcome: completed");page.navigate(h.base()+"/admin/clock-policies");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Priority incident commitment <script>").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("only availability may change");page.getByLabel("Policy availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save clock policy");assertThat(page.locator("main")).containsText("Disabled");
  }
 }
}
